"""Owner-approved policy handbook. No claim that every policy is live."""
from pathlib import Path
import sys, html, json
ROOT=Path(__file__).resolve().parents[1]
sys.path.insert(0,str(ROOT/'tmp/pdf-runtime'))
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, PageBreak, KeepTogether
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib import colors
import pypdfium2 as pdfium
from PIL import Image, ImageDraw

sections=[
('Using WeHouse',[
('Purpose and scope','WeHouse connects customers with accommodation, housing partners, service providers and provider-led activities. It also helps people find Roommates and coordinate with Friends. This handbook records the agreed platform policies as at 27 October 2026. It is an owner and legal-review draft, not published terms, proof of current feature availability or legal approval. The accepted booking or tenancy agreement must disclose the terms that apply to the particular transaction.'),
('Accounts and access','Use accurate account information and keep access credentials secure. Email users must be able to verify and recover access without a Google or Apple account. Signing in with a provider, confirming an email, approving a new device and recovering a password are separate processes. Users should be able to review and revoke their signed-in devices. A Team invitation grants only the responsibilities expressly assigned; ordinary users cannot make themselves staff.'),
('Identity and eligibility','NIN is not required to create a personal account, browse, add Friends or make an ordinary customer payment. Identity verification belongs to the person and can support their eligible provider roles. Nigerian providers may use NIN or an accepted identity alternative under the applicable verification process. Payout recipients also need the required identity and bank ownership checks. Identity approval does not replace property authority, a professional licence or business authorization.'),
('Fair and safe use','Do not impersonate another person, submit false documents, create fake reviews, misrepresent an offering, harass others or misuse private information. Report unsafe or misleading content through WeHouse. Verification and paid status must never be presented as a guarantee of safety or performance. Urgent emergencies require the appropriate local emergency services.')]),
('Property listings and management',[
('Homes, buildings and units','Homes are offered as Short Let or Long Let. A compound or apartment building can contain separate units with either arrangement or a mixture. Each physical unit keeps its own availability, occupants, agreement and money records, even where several units share a layout and price. Entire-unit and private-bedroom offers must identify shared spaces and must not sell overlapping occupancy. Studio / self-contained means zero separate bedrooms; Penthouse is an optional feature, not an automatic luxury rating.'),
('Information before booking','Present accurate photographs and descriptions, the actual unit or an explicitly accepted allocation, occupancy limit, bedrooms, beds, bathrooms, facilities, shared areas and material restrictions. Disclose the charged currency, price basis, compulsory charges, applicable taxes, caution or deposit, dates, local check-in/out time, cancellation terms and responsible operator. Private entrance and access details are available only to entitled participants.'),
('Authority and supporting evidence','A Partner must establish identity and authority to offer the property, through accepted ownership evidence or current letting/management authorization. Subletting requires the applicable permission. Businesses need relevant registration and representative authority. Address evidence alone does not establish ownership. Hotels and other accommodation providers must supply the operating approvals and safety evidence applicable to their location and offering. Required documents depend on the market and property; do not demand every alternative document from everyone.'),
('Host manages or WeHouse manages','Management responsibility is separate from ownership and property layout. WeHouse management requires an accepted operational arrangement. The Creator may configure an additional management percentage deducted from Partner earnings alongside base commission. Show the actual base, additional and combined rate and expected net when the Partner chooses management and submits for inspection. Obtain acceptance before new bookings; existing accepted bookings retain their saved rates. A Team member receives only their assigned access.')]),
('Stays, tenancy and later-year rent',[
('Short Let, Hotel and Long Let','Short Let uses nightly dates, including longer stays up to 90 days. A 30-day Short Let does not become Long Let automatically. Hotels use dated room availability and applicable rate terms. Long Let uses a separate tenancy agreement. Offer only terms the Partner accepts. Accepted three- or six-month terms and a one-year term are paid in full before handover; monthly payment is not offered for a one-year tenancy.'),
('Multi-year payment choice','Without Partner approval for later-year monthly payments, the full multi-year contract is paid upfront. With that approval, Year 1 is paid in full before handover. Each later year is funded by eight monthly payments in months 5-12 of the preceding year, beginning four months after actual handover. The tenant accepts the schedule, rent, fees and settlement arrangement. Optional automatic debit requires separate authorization; manual payment follows the same obligations. Failed debit is not payment and WeHouse does not finance unpaid rent.'),
('Later-year settlement and rent credit','Initial upfront rent, including a full multi-year payment, retains its accepted Payment Protection. Later-year monthly rent has no new protection hold: each verified payment deducts the disclosed WeHouse fee and settles the Partner share through the payment provider. Keep the full payment, fee, settlement and gross rent-credit record. The fee reduces Partner earnings, not the rent credited to the tenant. Distinguish paid, settlement pending and settled amounts.'),
('What each payment covers','For annual rent of NGN 1,200,000, eight equal payments are NGN 150,000 each. One payment funds 1.5 months of the target year: one complete month, NGN 50,000 toward the next and NGN 50,000 still needed to complete it. Show verified rent paid, complete months funded, partial-month credit, next-month balance and remaining annual rent. Allocate credit to its agreed contract year; advance credit is not proof that those months have already been occupied.'),
('Leaving early or paying a balance','Provide a way to contact the Partner about the remaining rent, the period funded and a proposed exit. Later-year rent is rent paid to the Partner, not refundable savings held by WeHouse. Cancelling a debit does not cancel the tenancy. Exit, notice, any balance and any valid refund follow the accepted tenancy agreement and applicable law. There is no automatic eviction, blanket forfeiture or automatic refund merely because the tenant stops paying. The lawful effect of a partial-month credit must be addressed in the tenancy agreement.')]),
('Payments, protection and refunds',[
('Prices, fees and receipts','Show the total, charged currency, discounts and compulsory charges before payment. Use the actual published Creator-configured commission for the product, including Experiences; no numerical commission is approved by this handbook. Deduct the agreed Partner commission from the applicable payment, rather than charging the annual fee again on each monthly contribution. Save the accepted rate and calculated fee with each payment. Hotels do not carry a WeHouse guest reservation fee. Other reservation fees or customer service charges must be separately disclosed where applicable.'),
('Payment Protection','Only verified payment-provider confirmation establishes a successful charge. Payment Protection records an eligible payment and its authorized release, dispute or refund under the accepted transaction terms; it is not a promise that all disputes or losses will be reimbursed. Initial fulfillment and issue-reporting controls apply before release as disclosed. Later-year monthly rent follows the separate direct-settlement policy on the preceding page. Keep caution or deposits distinct from platform earnings.'),
('Standard cancellation deadline','For the standard refundable Short Let, Hotel, requested Service and Experience booking, a customer receives a full refund when cancelling at least 24 hours before the scheduled start. Display the exact deadline, date, time and relevant timezone before payment. Provider or host cancellation gives a full refund. Partners choose approved platform policy options rather than writing arbitrary policies. Existing bookings keep their accepted terms. Late cancellation, no-show and any other offered rate must disclose the applicable terms; this handbook invents no universal late penalty. Long Let has separate tenancy terms.'),
('Requests, deductions and confirmation','Customers need a route to request a refund or dispute a charge, including when money has already been released. Explain the proposed amount and deduction reasons before confirmation. A refund is pending until the payment provider confirms completion; failed or uncertain refunds remain traceable. Refunds cannot exceed the verified payment. Caution claims require itemized evidence and a route for the customer to respond; silence must not automatically award money to the Partner. Undisputed refundable amounts must be handled separately.'),
('Shared booking costs','Invited participants must explicitly accept their shares. Track each payer, amount, verified payment and refund separately. A partial collection must not imply the booking is fully funded. Disclose the payment deadline and outcome for missing, late, duplicate or failed shares before anyone pays. Do not charge a participant for another person without authorization. Availability and confirmation remain subject to the booking agreement. Sharing booking costs does not create a future-rent lending product.')]),
('Services, activities and reviews',[
('Request a service','A customer uses Request a service to agree work through chat. Record the scope, deliverables and exclusions, date or timing, location, price and applicable cancellation terms. A public starting price is not the final agreed quote. The customer must explicitly accept the actual quote before paying; a provider changing a displayed price does not retrospectively change an accepted agreement.'),
('Book an activity','Experiences are dated provider-led activities, such as tours, walks and cooking or creative classes. They belong within Services and the existing provider workspace, identity, wallet, Inbox and Help. A new activity host does not need to offer an unrelated service first. Existing Service Workers may apply to host suitable activities. Shows, parties and nightlife are outside the agreed catalog.'),
('Activity information and approval','Show the host, description, schedule and timezone, duration, meeting point, capacity, per-person and total price, inclusions, exclusions, participation restrictions and relevant accessibility or safety information. Review the expertise, venue permission, credentials, licences, permits or insurance required for the category and market. Identity verification alone does not establish competence. Approval and actual session availability are required before publication and booking.'),
('Attendance and completion','Do not treat a prepared session or a payment as proof of attendance. Record the actual booked session and the appropriate attendance and completion confirmations. Apply the accepted payment, release and cancellation policy to that booking. Changes to a public activity description must not silently rewrite what an existing customer bought.'),
('Genuine reviews','Reviews must connect to a genuine eligible stay, tenancy, completed service or attended activity. A Long Let tenant should have a route to review an actual tenancy without waiting for a multi-year contract to end. Do not allow self-reviews, fabricated transactions or paid status to create review eligibility. Provide reporting and moderation for abusive or misleading reviews without suppressing honest criticism merely because it is unfavorable.')]),
('Friends, Roommates and communications',[
('Separate relationships','Adding a Roommate as a Friend does not replace or change the Roommate relationship, its permissions or a shared housing agreement. Friend access does not automatically grant property access, financial authority or Team permissions. Roommate discovery and optional matching must respect the preferences and profile information the person chose to share.'),
('Suggest a plan','Suggest a plan and Plan together help accepted Friends coordinate privately within their conversation. A plan may concern a meal, walk, activity or trip. It does not create a booking, payment obligation, paid Experience or Roommate agreement. Any accommodation or activity purchase requires a separate explicit booking. Friend groups are outside the currently approved build scope.'),
('Messages and shared listings','A shared property, Hotel, Service or Experience should link to the correct authorized offering for sender and recipient. Sharing a card does not bypass availability, privacy or payment controls. Users must have clear controls for messaging, calls, reactions, notifications, blocking and reporting. Do not expose private identity evidence, bank information, internal case notes or access instructions through public cards or notification previews.'),
('Notifications and preferences','Send notifications about the relevant conversation, booking, payment or case and link to the appropriate authorized record. Optional followed-search and marketing alerts depend on the user preferences and genuinely matching results. Explain what each preference controls. Security and essential transaction communications must be distinguished from optional marketing. A displayed setting must accurately describe the delivery methods available to that user.')]),
('Privacy, support and fair decisions',[
('Personal information','Use account, identity, contact, payment, booking and location information for the disclosed platform purposes. Keep private identity evidence, precise access details, bank details and internal notes restricted to entitled participants and authorized staff. Collect only the evidence required for the person, offering and market. Public media must not reveal private verification documents.'),
('Location and personalization','Use the correct country and its administrative divisions rather than treating every country as Nigerian State/LGA. Public approximate location and private exact address have different access needs. Ask permission for device location and allow a manual location choice. Explain optional personalization and followed-search uses; do not infer unrestricted tracking consent from a location preference.'),
('Access, correction and deletion','Users need a route to request access or export, correction, closure and deletion of their personal data. Explain how to submit a request and verify the requester. Delete or anonymize eligible information and explain any records retained for payments, disputes or legal obligations, the reason and applicable retention period. Do not promise that account closure immediately erases every financial record or removes another person\'s legitimate transaction history.'),
('Help, reports and appeals','Route requests to the appropriate support, property, provider, finance or security responsibility using the actual issue and related record. Restrict access by assigned authority rather than exposing every message to all staff. Give the user a confirmation, status and route to follow up; a report button must produce an actionable record. Keep internal notes separate from customer-visible replies. Record material decisions and allow relevant evidence and a review or appeal route.'),
('Rights and publication','This handbook does not waive mandatory consumer, privacy or tenancy rights. Before publication, complete the legal entity and contact details, jurisdiction-specific tenancy and cancellation requirements, applicable retention periods and market-specific documents. Legal review should consider the Nigerian Federal Competition and Consumer Protection Act, including advance-booking cancellation rules, and applicable privacy and tenancy law. Reference: fccpc.gov.ng/wp-content/uploads/2022/07/FCCPA-2018.pdf. No legal approval is claimed.')]),
('Pro, discounts, promotion and markets',[
('Core access and Pro','Essential fulfillment, access instructions, verification, safety, reporting, support and payment records remain core capabilities. Pro may provide optional business tools and reporting. Disclose the actual package, price, billing period, renewal, cancellation and included tools before purchase. Paid membership does not itself prove trust, professional competence or property approval.'),
('Optional discounts','Discounts are optional. Show the base price, funding source, eligibility, effective period and final amount. WeHouse may fund a discount from its own share while preserving the Partner\'s accepted earnings. A location or campaign rule must identify eligible offerings and its dates, rather than silently changing all agreements. Existing bookings keep their accepted price and refunds use the actual amount paid. Long Let discounts apply to Year 1; later-year contributions keep their accepted basis.'),
('Sponsored offerings','A campaign promotes a specific eligible property, Service or Experience. Match location, dates, budget and service needs first; exclude unavailable, suspended or unapproved offers. Rotate eligible campaigns fairly within the matching pool, limit repeated exposure and label the placement Sponsored. Ordinary search must remain useful without payment. One campaign does not automatically promote every unit belonging to a Partner or crowd results with duplicates.'),
('Promotion price and reporting','Before buying promotion, disclose the actual price, period, target offering and placement terms. Report real views, opens and bookings separately. Promotion does not guarantee a booking, approval or safety. No universal campaign price or booking probability is established by this handbook; use the configured offer accepted at purchase.'),
('Markets, currency and effective terms','Nigeria is the initial payment market. Display the currency actually charged; a saved viewing region must not silently convert an existing obligation. A new market requires its appropriate location data, currency, payment provider, refunds, settlements, identity and local operating requirements before activation. Publish changes with clear effective dates and preserve accepted transaction terms. This handbook describes agreed policy; availability in the app must be communicated accurately.')])]

out=ROOT/'output/pdf/WeHouse_Platform_Policies.pdf';out.parent.mkdir(parents=True,exist_ok=True)
preview=ROOT/'tmp/pdfs/platform-policies';preview.mkdir(parents=True,exist_ok=True)
styles=getSampleStyleSheet()
styles.add(ParagraphStyle(name='SectionTitle',fontName='Helvetica-Bold',fontSize=23,leading=27,textColor=colors.HexColor('#243D37'),spaceAfter=15))
styles.add(ParagraphStyle(name='PolicyHead',fontName='Helvetica-Bold',fontSize=10.5,leading=14,spaceBefore=10,spaceAfter=4,textColor=colors.HexColor('#243D37')))
styles.add(ParagraphStyle(name='PolicyText',fontName='Helvetica',fontSize=10,leading=14.2,spaceAfter=4,textColor=colors.HexColor('#28332F')))
styles.add(ParagraphStyle(name='Kicker',fontName='Helvetica-Bold',fontSize=8,leading=11,spaceAfter=10,textColor=colors.HexColor('#65796F')))
story=[]
for i,(title,policies) in enumerate(sections):
 if i:story.append(PageBreak())
 story.append(Paragraph(f'WEHOUSE / PLATFORM POLICIES / {i+1:02}',styles['Kicker']))
 story.append(Paragraph(title,styles['SectionTitle']))
 for heading,text in policies:
  story.append(KeepTogether([Paragraph(html.escape(heading),styles['PolicyHead']),Paragraph(html.escape(text),styles['PolicyText'])]))
def footer(c,doc):
 c.setStrokeColor(colors.HexColor('#DCE5DF'));c.line(43,42,552,42)
 c.setFont('Helvetica',8);c.setFillColor(colors.HexColor('#65796F'))
 c.drawString(43,28,'WEHOUSE | OWNER & LEGAL REVIEW DRAFT | 27 OCTOBER 2026');c.drawRightString(552,28,str(doc.page))
SimpleDocTemplate(str(out),pagesize=(595.28,841.89),leftMargin=43,rightMargin=43,topMargin=37,bottomMargin=57,title='WeHouse Platform Policies',author='WeHouse').build(story,onFirstPage=footer,onLaterPages=footer)
pdf=pdfium.PdfDocument(str(out));texts=[]
for i,page in enumerate(pdf):
 texts.append(page.get_textpage().get_text_range());page.render(scale=1.1).to_pil().save(preview/f'page-{i+1:02}.png')
assert len(pdf)==len(sections),f'Unexpected section overflow: {len(pdf)} pages'
assert all(len(t)>600 for t in texts)
assert not any(x in '\n'.join(texts) for x in ['\ufffd','\u25a0','PR #118','migration','Supabase'])
sheet=Image.new('RGB',(1050,((len(pdf)+2)//3)*500),'#E8EDE9');draw=ImageDraw.Draw(sheet)
for i in range(len(pdf)):
 im=Image.open(preview/f'page-{i+1:02}.png');im.thumbnail((330,465));x=(i%3)*350+10;y=(i//3)*500+22;sheet.paste(im,(x,y));draw.text((x,y-17),f'Page {i+1}',fill='#243D37')
sheet.save(preview/'contact-sheet.png')
print(json.dumps({'pdf':str(out),'pages':len(pdf),'bytes':out.stat().st_size,'preview':str(preview/'contact-sheet.png')}))
